// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 putAmount, uint256 collectAmount, address actor, uint256 unlockTimeOffset) public {
        vm.assume(putAmount <= VALUE_CAP);
        // Wide but meaningful domain: use a real depositor, non-zero deposit, bounded amounts and future unlock offset.
        putAmount = bound(putAmount, 1, 100 ether);
        collectAmount = bound(collectAmount, 1, 10 ether);
        unlockTimeOffset = bound(unlockTimeOffset, 1, 365 days);
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);

        // Give the depositor funds and deposit into C via Put (the public entry that creates Acc[actor]).
        vm.deal(actor, putAmount);
        vm.prank(actor);
        c.Put{value: putAmount}(block.timestamp + unlockTimeOffset);

        // Try to collect a positive amount before the unlock time (block.timestamp is still < unlockTime).
        // In the reference this must not change Acc; in the mutant it may succeed and reduce Acc[actor].balance.
        uint256 balanceBefore = 0;
        (uint256 unlockBefore, uint256 balanceBefore_) = c.Acc(actor);
        balanceBefore = balanceBefore_;
        unlockBefore;

        vm.deal(actor, collectAmount);
        vm.prank(actor);
        // We do not assert on the revert itself: the property is about state not being mutably updated.
        try c.Collect{value: 0}(collectAmount) {
            // call may succeed in the mutant; reference should have reverted
        } catch {
            // reference should land here for premature collect
        }

        (uint256 unlockAfter, uint256 balanceAfter) = c.Acc(actor);
        unlockAfter;

        // GENERAL RULE: a premature Collect (before unlockTime) must not be able to reduce the recorded stake below its pre-call value.
        // Reference: always holds (premature Collect always reverts/no-ops). Mutant: holds only if the buggy check happens to block the amount,
        // so there is an input where it breaks.
        assertTrue(balanceAfter >= balanceBefore);
    }
}
